(43482, 'Jonah 1:16', 'Jonah', 1, 16, 'په دې کار هغه سړي د څښتن څخه ډېر ووېرېدل او هغوی څښتن ته قرباني وړاندې کړه او نذرونه یې ورکړل.', 'په دې کار هغه سری د چشتن چخه دېر ووېرېدل او هغوی چشتن ته قربانی وراندې کره او نذرونه یې ورکرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/jonah001_verse_016.mp3', 'https://drive.google.com/file/d/11_k8Q5jlb0iPeSfUi5PHwYfIOamLFGpe/preview', 1761237842, 1761237842),
(43483, 'Jonah 1:17', 'Jonah', 1, 17, 'څښتن یو لوی ماهي ولېږه چې یونس ژوندی تیر کړي او یونس درې ورځې او درې شپې د ماهي په ګېډه کې ؤ.', 'چشتن یو لوی ماهی ولېزه چې یونس ژوندی تیر کری او یونس درې ورجې او درې شپې د ماهی په ګېده کې و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/jonah001_verse_017.mp3', 'https://drive.google.com/file/d/13tqNIdlaufOWWpD4w86ofioMOib06-wq/preview', 1761237842, 1761237842),
(43484, 'Songofsongs 5:1', 'Songofsongs', 5, 1, 'زما دُنيا، زما ناوې، زۀ په خپل باغ کښې داخل شوے يمه. زۀ د مُر چيړ او خوشبوداره مصالحې راټولومه. ما خپل ګبين د شاتو سره وخوړلونه، او زۀ خپل پئ او مے څښمه. ښځې اے عاشقانو، وخورئ او وڅښئينه. او د مينې نه مست شئينه.', 'زما دنیا، زما ناوې، زۀ په خپل باغ کشې داخل شوے یمه. زۀ د مر چیر او خوشبوداره مصالحې راتولومه. ما خپل ګبین د شاتو سره وخورلونه، او زۀ خپل پی او مے چشمه. شجې اے عاشقانو، وخوری او وچشیینه. او د مینې نه مست شیینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43485, 'Songofsongs 5:2', 'Songofsongs', 5, 2, 'زۀ اودۀ ومه خو زما زړۀ بېدار وونه، غوږ شه. زما جانان ور ټکوينه. ”زما د زړۀ دُنيا او محبوبې ور کولاو کړه، زما ګوګوشتکې، زما بې‌عېبه مينې. محبوب زما سر په شبنم باندې لوند دېنه، او د شپې پرخې مې وېښتۀ لوندۀ کړى دينه.“ محبوبه', 'زۀ اودۀ ومه خو زما زرۀ بېدار وونه، غوز شه. زما جانان ور تکوینه. ”زما د زرۀ دنیا او محبوبې ور کولاو کره، زما ګوګوشتکې، زما بې‌عېبه مینې. محبوب زما سر په شبنم باندې لوند دېنه، او د شپې پرخې مې وېشتۀ لوندۀ کری دینه.“ محبوبه', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43486, 'Songofsongs 5:3', 'Songofsongs', 5, 3, 'ما خو جامې ويستلې دينه، نو دا بيا دوباره واچوم څۀ؟ ما خپلې پښې وينځلې دينه، بيا دا دوباره په خاورو ګنده کړم څۀ؟', 'ما خو جامې ویستلې دینه، نو دا بیا دوباره واچوم چۀ؟ ما خپلې پشې وینجلې دینه، بیا دا دوباره په خاورو ګنده کرم چۀ؟', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43487, 'Songofsongs 5:4', 'Songofsongs', 5, 4, 'زما جانان خپل لاس په ور کښې راوږد کړونه، نو زما زړۀ د هغۀ دپاره په درزېدو شونه.', 'زما جانان خپل لاس په ور کشې راوزد کرونه، نو زما زرۀ د هغۀ دپاره په درزېدو شونه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43488, 'Songofsongs 5:5', 'Songofsongs', 5, 5, 'نو زۀ راپاڅېدم چې خپل جانان ته ور کولاو کړمه. زما د لاسونو نه عطر په څڅېدو شونه. زما د ګوتو نه د مُر چيړ په څڅېدو شونه کله چې ما د ور کُنډه راښکله.', 'نو زۀ راپاچېدم چې خپل جانان ته ور کولاو کرمه. زما د لاسونو نه عطر په چچېدو شونه. زما د ګوتو نه د مر چیر په چچېدو شونه کله چې ما د ور کنده راشکله.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43489, 'Songofsongs 5:6', 'Songofsongs', 5, 6, 'ما خپل جانان ته ور کولاو کړونه، خو هغه بيا تلے وو، نو زۀ سخته پرېشانه شومه، ما هغه ولټولو، خو هغه مې پېدا نۀ کړونه، ما هغۀ ته آواز وکړونه، خو هغۀ ما ته جواب رانۀ کړونه.', 'ما خپل جانان ته ور کولاو کرونه، خو هغه بیا تلے وو، نو زۀ سخته پرېشانه شومه، ما هغه ولتولو، خو هغه مې پېدا نۀ کرونه، ما هغۀ ته اواز وکرونه، خو هغۀ ما ته جواب رانۀ کرونه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43490, 'Songofsongs 5:7', 'Songofsongs', 5, 7, 'کومو څوکيدارانو چې په ښار کښې ګشت کولونه نو هغوئ زۀ ونيولم، هغوئ زۀ ووهلمه او په وهلو يې تکه شنه کړمه، او د ښار د دېوالونو چوکيدارانو زما د مخ نه پلو اوچت کړونه.', 'کومو چوکیدارانو چې په شار کشې ګشت کولونه نو هغوی زۀ ونیولم، هغوی زۀ ووهلمه او په وهلو یې تکه شنه کرمه، او د شار د دېوالونو چوکیدارانو زما د مخ نه پلو اوچت کرونه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43491, 'Songofsongs 5:8', 'Songofsongs', 5, 8, 'اے د يروشلم ښځو، ما سره دا وعده وکړئينه، کۀ چرې تاسو زما جانان وليدلو، هغۀ ته ووائينه چې زۀ د هغۀ د مينې په وجه کمزورې شوې يمه. ښځې', 'اے د یروشلم شجو، ما سره دا وعده وکریینه، کۀ چرې تاسو زما جانان ولیدلو، هغۀ ته ووایینه چې زۀ د هغۀ د مینې په وجه کمزورې شوې یمه. شجې', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43492, 'Songofsongs 5:9', 'Songofsongs', 5, 9, 'اے په ټولو پېغلو کښې ښائسته جينۍ، ستا جانان د نورو سړو نه کوم خاص خصوصيت لرينه؟ په هغۀ کښې داسې څۀ خاص دينه، چې مونږ تا سره دا لوظ وکړونه؟ محبوبه', 'اے په تولو پېغلو کشې شایسته جینی، ستا جانان د نورو سرو نه کوم خاص خصوصیت لرینه؟ په هغۀ کشې داسې چۀ خاص دینه، چې مونز تا سره دا لوظ وکرونه؟ محبوبه', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43493, 'Songofsongs 5:10', 'Songofsongs', 5, 10, 'زما جانان سور سپين دېنه، او په لسو زرو کښې د ټولو نه اعلىٰ دېنه.', 'زما جانان سور سپین دېنه، او په لسو زرو کشې د تولو نه اعلی دېنه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43494, 'Songofsongs 5:11', 'Songofsongs', 5, 11, 'د هغۀ سر د سوچه سرو زرو دېنه، د هغۀ وېښتۀ وَل وَل دينه، او لکه د کارغۀ په شان تور دېنه.', 'د هغۀ سر د سوچه سرو زرو دېنه، د هغۀ وېشتۀ ول ول دینه، او لکه د کارغۀ په شان تور دېنه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43495, 'Songofsongs 5:12', 'Songofsongs', 5, 12, 'د هغۀ سترګې د ګوګوشتکو په شان دينه چې د اوبو د چينو په خوا کښې وينه سپينې ګوګوشتکې لکه د پئيو په شان چې د تالاب په خوا کښې ناستې وينه.', 'د هغۀ سترګې د ګوګوشتکو په شان دینه چې د اوبو د چینو په خوا کشې وینه سپینې ګوګوشتکې لکه د پییو په شان چې د تالاب په خوا کشې ناستې وینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43496, 'Songofsongs 5:13', 'Songofsongs', 5, 13, 'د هغۀ اننګى د باغ په شان دينه، چې د خوشبودارو بوټو نه ډک وينه. د هغۀ شونډې د لاله د ګل په شان دينه، لکه چې د مُر په چيړ خوشبويه شوې وينه.', 'د هغۀ اننګی د باغ په شان دینه، چې د خوشبودارو بوتو نه دک وینه. د هغۀ شوندې د لاله د ګل په شان دینه، لکه چې د مر په چیر خوشبویه شوې وینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43497, 'Songofsongs 5:14', 'Songofsongs', 5, 14, 'د هغۀ لاسونه د سرو زرو سيخونه دينه، چې په دې کښې قيمتى کاڼى لګېدلى وينه. د هغۀ بدن لکه د هاتى د غاښونو په شان سپين دېنه، او چې په کښې نيلم کاڼى لګېدلى وينه.', 'د هغۀ لاسونه د سرو زرو سیخونه دینه، چې په دې کشې قیمتی کانی لګېدلی وینه. د هغۀ بدن لکه د هاتی د غاشونو په شان سپین دېنه، او چې په کشې نیلم کانی لګېدلی وینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43498, 'Songofsongs 5:15', 'Songofsongs', 5, 15, 'د هغۀ پښې د سنګِ مرمرو د ستنو په شان دينه چې په سرو زرو کښې لګولے شوې وينه. د هغۀ شکل د لبنان د غرونو د خاص دِيار په شان ښکارينه.', 'د هغۀ پشې د سنګ مرمرو د ستنو په شان دینه چې په سرو زرو کشې لګولے شوې وینه. د هغۀ شکل د لبنان د غرونو د خاص دیار په شان شکارینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43499, 'Songofsongs 5:16', 'Songofsongs', 5, 16, 'هغه ډېره خوږه خولۀ لرينه، هغه په هر لحاظ زړۀ راښکونکے دېنه، نو، اے د يروشلم ښځو، زما جانان او زما آشنا دغه شان دېنه.', 'هغه دېره خوزه خولۀ لرینه، هغه په هر لحاظ زرۀ راشکونکے دېنه، نو، اے د یروشلم شجو، زما جانان او زما اشنا دغه شان دېنه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237842, 1761237842),
(43500, 'Ecclesiastes 9:1', 'Ecclesiastes', 9, 1, 'نو ما په دې ټولو کارونو باندې فکر وکړ، ترڅو دا هرڅه وڅېړم. زه دې نتیجې ته ورسېدم چې نېکان او هوښیاران او د هغوی کارونه د خدای په لاس کې دي. دا چې له انسان سره مینه کیږي یا کرکه، خو هېڅوک په دې نه پوهیږي چې د انسان په راتلونکې کې به څه پېښیږي.', 'نو ما په دې تولو کارونو باندې فکر وکر، ترچو دا هرچه وچېرم. زه دې نتیجې ته ورسېدم چې نېکان او هوشیاران او د هغوی کارونه د خدای په لاس کې دی. دا چې له انسان سره مینه کیزی یا کرکه، خو هېچوک په دې نه پوهیزی چې د انسان په راتلونکې کې به چه پېشیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ecclesiastes_9_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237842, 1761237842),
(43501, 'Ecclesiastes 9:2', 'Ecclesiastes', 9, 2, 'څه چې په یو پېښیږي هغه په بل هم پېښیږي نو د ټولو پای یو دی څوک چې نېک کاره وي او څوک چې بدکاره وي څوک چې پوره پاک وي او څوک چې ناپاک وي څوک چې قرباني ورکوي او څوک چې قرباني نه ورکوي څه چې له ښه سړي سره کیږي هغه د ګناهکار سره هم کیږي څه چې له قسم خوړونکي سره کیږي هغه له قسم څخه وېرېدونکي سره هم کیږي', 'چه چې په یو پېشیزی هغه په بل هم پېشیزی نو د تولو پای یو دی چوک چې نېک کاره وی او چوک چې بدکاره وی چوک چې پوره پاک وی او چوک چې ناپاک وی چوک چې قربانی ورکوی او چوک چې قربانی نه ورکوی چه چې له شه سری سره کیزی هغه د ګناهکار سره هم کیزی چه چې له قسم خورونکی سره کیزی هغه له قسم چخه وېرېدونکی سره هم کیزی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ecclesiastes_9_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43502, 'Ecclesiastes 9:3', 'Ecclesiastes', 9, 3, 'دا بله بدبختي ده چې د اسمان لاندې په هر شي باندې پېښیږي، چې د ټولو پای یو دی. همدا شان د انسانانو زړونه له شرارت نه ډک دي، او ترڅو چې ژوندي دي په زړونو کې یې جهالت وي، بیا دوی له مړو سره یوځای کیږي.', 'دا بله بدبختی ده چې د اسمان لاندې په هر شی باندې پېشیزی، چې د تولو پای یو دی. همدا شان د انسانانو زرونه له شرارت نه دک دی، او ترچو چې ژوندی دی په زرونو کې یې جهالت وی، بیا دوی له مرو سره یوجای کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ecclesiastes_9_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43503, 'Ecclesiastes 9:4', 'Ecclesiastes', 9, 4, 'په یقین سره څوک چې د ژوندیو په منځ کې دی هغه په دې تمه دی چې له مړ زمري نه ژوندی سپی ښه دی.', 'په یقین سره چوک چې د ژوندیو په منج کې دی هغه په دې تمه دی چې له مر زمری نه ژوندی سپی شه دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ecclesiastes_9_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
(43504, 'Ecclesiastes 9:5', 'Ecclesiastes', 9, 5, 'ځکه ژوندي په دې پوهیږي چې دوی به مړه شي، خو مړي په دې هېڅ نه پوهیږي. مړي نور هېڅ اجوره نه لري او حتی د هغوی یاد له منځه ځي', 'جکه ژوندی په دې پوهیزی چې دوی به مره شی، خو مری په دې هېچ نه پوهیزی. مری نور هېچ اجوره نه لری او حتی د هغوی یاد له منجه جی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Ecclesiastes_9_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237842, 1761237842),
